    handlelCollect(item){
      collect({
        knowledgeId: item.id,
        isDeleted: 0,
        userId: this.userInfo.userId
      }).then(res=>{
        this.$message({
          message: '操作成功！',
          type: 'success'
        });
        this.answerSearch()
      })
    },
    handlelStudy(item){
      learnSave({
