      }).then(res=>{
        this.$message({
          message: '操作成功！',
          type: 'success'
        });
        this.answerSearch()
      })
    },
    getHistortList(val) {
      historyAnswerList({resourceCondition: val}).then(res => {
        if(this.isHistory){
          this.active = 0
          this.isHistory = false
        }
        this.historyList = res.data
        for(let i=0; i<this.historyList.length; i++) {
          let item = this.historyList[i]
          if(item.createTime != null) {
            item.time = formatDate(new Date(item.createTime), 'yyyy年MM月dd日')
          }
        }
      })
    },
    // 历史问答搜索
    querySearchAsync(queryString, cb) {
      if(queryString == '') {
        cb([])
        this.getHistortList('')
      }
      else {
        historyAnswerList({resourceCondition: queryString}).then(res => {
          for(let i=0; i<res.data.length; i++) {
            res.data[i].value = res.data[i].problem
          }
          cb(res.data)
        })
      }
    },
    handleSelect(item) {
      this.getHistortList(item.problem)
    },
    handleHistorySearch() {
      this.getHistortList(this.historySearchText)
    },
    // 查看历史详情
    seeHistoryDetail(item,index) {
      if(index){
        this.active = index;
      }
      this.isHistory = true
      this.searchText = item.problem
      this.answerSearch()
    },
    delHistory(item) {
      this.$confirm('确定删除该历史记录?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        historyAnswerDelete({id: item.id}).then(res => {
          this.$message({
            message: '删除成功！',
            type: 'success'
          });
          this.getHistortList()
        })
      })
    },
    handleSearchText() {
      if(this.searchText == '') this.isSearch = false
    },
    // 搜索答案
    answerSearch(val) {
      this.searchText = this.searchText.trim()

      if(this.searchText == '' && val) {
        this.$message({
          message: '请输入搜索内容！',
          type: 'warning'
        });
      }else {
        knowledgeList({
          current: 1,
          size: 999,
          resourceCondition: this.searchText,
        }).then(res => {
          if(res.data.length === 0){
            this.$message({
              message: '未查询到相关知识！',
              type: 'warning'
            });
            return
          }

          this.searchContentList = res.data
          this.isSearch = true
          this.getHistortList()
        })
      }

    },
